alter table roles drop constraint if exists roles_code_check;
alter table roles add constraint roles_code_check check (code in ('ADMINISTRATIVE_EMPLOYEE','FIELD_INSPECTOR','PROTECTION_SAFETY_OFFICER','OPERATIONS_OFFICER','CENTER_INSPECTOR','INSPECTION_EXAMINER','INSPECTION_OFFICER_EMPLOYEE','INSPECTION_OFFICER','FIELD_OFFICER'));
insert into roles (code,name_ar) values ('CENTER_INSPECTOR','مفتش مركز'),('INSPECTION_EXAMINER','مفتش فاحص'),('INSPECTION_OFFICER_EMPLOYEE','موظف مفتش'),('INSPECTION_OFFICER','ضابط التفتيش'),('FIELD_OFFICER','الضابط الميداني') on conflict (code) do update set name_ar=excluded.name_ar;
insert into app_users (display_name,login_name,employee_number,role_code,is_active) values ('ABDULLA ALMAJED','abdulla.center','FS-CEN-001','CENTER_INSPECTOR',true),('ABDULLA ALMAJED','abdulla.examiner','FS-EXM-001','INSPECTION_EXAMINER',true),('ABDULLA ALMAJED','abdulla.review','FS-REV-001','INSPECTION_OFFICER_EMPLOYEE',true),('ABDULLA ALMAJED','abdulla.inspectionofficer','FS-IOF-001','INSPECTION_OFFICER',true),('ABDULLA ALMAJED','abdulla.fieldofficer','FS-FLD-001','FIELD_OFFICER',true) on conflict (login_name) do update set display_name=excluded.display_name, role_code=excluded.role_code, is_active=excluded.is_active, updated_at=now();
create table if not exists field_inspection_requests (id uuid primary key default gen_random_uuid(), facility_id uuid not null references facilities(id), requested_by uuid references app_users(id), reason text not null check (reason in ('ملاحظة مخالفة','اشتباه في وجود نقص في أنظمة السلامة','معدات حماية غير متوفرة أو غير واضحة','تغيير في المبنى','مواد خطرة','حالة تحتاج مراجعة','أخرى')), notes text, photo_paths jsonb not null default '[]'::jsonb, priority text not null default 'Normal' check (priority in ('Normal','High','Urgent')), status text not null default 'New' check (status in ('New','Approved','Rejected','Assigned','Completed')), reviewed_by uuid references app_users(id), reviewed_at timestamptz, review_reason text, assignment_id uuid references inspection_assignments(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists violation_reviews (id uuid primary key default gen_random_uuid(), violation_id uuid not null references violations(id) on delete cascade, reviewed_by uuid references app_users(id), action text not null check (action in ('Approved','Rejected','Returned')), reason text not null, created_at timestamptz not null default now());
alter table violations add column if not exists created_by uuid references app_users(id);
alter table violations add column if not exists inspector_role text;
alter table violations add column if not exists review_status text not null default 'Pending Review' check (review_status in ('Pending Review','Approved','Rejected','Returned'));
alter table violations add column if not exists review_reason text;
alter table violations add column if not exists reviewed_by uuid references app_users(id);
alter table violations add column if not exists reviewed_at timestamptz;
alter table inspections add column if not exists inspection_type text not null default 'Violation Inspection' check (inspection_type in ('Violation Inspection','Pre-Opening Inspection','Follow-Up Inspection'));
create index if not exists field_requests_status_idx on field_inspection_requests (status,priority,created_at);
create index if not exists violation_reviews_violation_idx on violation_reviews (violation_id,created_at);
